# Rust Cache Action

A GitHub Action that implements smart caching for rust/cargo projects with
sensible defaults.

## Example usage

```yaml
- uses: actions/checkout@v6

# selecting a toolchain either by action or manual `rustup` calls should happen
# before the plugin, as the cache uses the current rustc version as its cache key
- run: rustup toolchain install stable --profile minimal

- uses: Swatinem/rust-cache@v2
  with:
    # The prefix cache key, this can be changed to start a new cache manually.
    # default: "v0-rust"
    prefix-key: ""

    # A cache key that is used instead of the automatic `job`-based key,
    # and is stable over multiple jobs.
    # default: empty
    shared-key: ""

    # An additional cache key that is added alongside the automatic `job`-based
    # cache key and can be used to further differentiate jobs.
    # default: empty
    key: ""

    # If the automatic `job`-based cache key should include the job id.
    # default: "true"
    add-job-id-key: ""

    # Whether the a hash of the rust environment should be included in the cache key.
    # This includes a hash of all Cargo.toml/Cargo.lock files, rust-toolchain files,
    # and .cargo/config.toml files (if present), as well as the specified 'env-vars'.
    # default: "true"
    add-rust-environment-hash-key: ""

    # A whitespace separated list of env-var *prefixes* who's value contributes
    # to the environment cache key.
    # The env-vars are matched by *prefix*, so the default `RUST` var will
    # match all of `RUSTC`, `RUSTUP_*`, `RUSTFLAGS`, `RUSTDOC_*`, etc.
    # default: "CARGO CC CFLAGS CXX CMAKE RUST"
    env-vars: ""

    # The cargo workspaces and target directory configuration.
    # These entries are separated by newlines and have the form
    # `$workspace -> $target`. The `$target` part is treated as a directory
    # relative to the `$workspace` and defaults to "target" if not explicitly given.
    # default: ". -> target"
    workspaces: ""

    # Additional non workspace directories to be cached, separated by newlines.
    cache-directories: ""

    # Determines whether workspace `target` directories are cached.
    # If `false`, only the cargo registry will be cached.
    # default: "true"
    cache-targets: ""

    # Determines if the cache should be saved even when the workflow has failed.
    # default: "false"
    cache-on-failure: ""

    # Determines which crates are cached.
    # If `true` all crates will be cached, otherwise only dependent crates will be cached.
    # Useful if additional crates are used for CI tooling.
    # default: "false"
    cache-all-crates: ""

    # Similar to cache-all-crates.
    # If `true` the workspace crates will be cached.
    # Useful if the workspace contains libraries that are only updated sporadically.
    # default: "false"
    cache-workspace-crates: ""

    # Determines whether the cache should be saved.
    # If `false`, the cache is only restored.
    # Useful for jobs where the matrix is additive e.g. additional Cargo features,
    # or when only runs from `master` should be saved to the cache.
    # default: "true"
    save-if: ""
    # To only cache runs from `master`:
    save-if: ${{ github.ref == 'refs/heads/master' }}

    # Determines whether the cache should be restored.
    # If `true` the cache key will be checked and the `cache-hit` output will be set
    # but the cache itself won't be restored
    # default: "false"
    lookup-only: ""

    # Specifies what to use as the backend providing cache
    # Can be set to "github", or "warpbuild"
    # default: "github"
    cache-provider: ""

    # Determines whether to cache the ~/.cargo/bin directory.
    # default: "true"
    env.RUNNER_ENVIRONMENT !== "github-hosted" ||
    env.RUNNER_OS !== "Linux"
  ) {
    throw new Error(
      "Preparation requires a disposable GitHub-hosted Linux runner",
    );
  }
  if (!(await lstat(resolve(root))).isDirectory()) {
    throw new Error("Preparation root must be a real directory, not a symlink");
  }
  const release = await readFile(join(root, "etc/os-release"), "utf8");
  if (!/^ID=(?:ubuntu|"ubuntu"|'ubuntu')[ \t]*$/m.test(release)) {
    throw new Error("Preparation requires Ubuntu");
  }
}

async function candidate(root, imagePath) {
  let path = root;
  for (const component of imagePath.slice(1).split("/")) {
    path = join(path, component);
    try {
      const info = await lstat(path);
      if (!info.isDirectory()) {
        return {
          path: imagePath,
          reason: "symlink or non-directory component",
        };
      }
    } catch (error) {
      if (error.code === "ENOENT") return { path: imagePath, reason: "absent" };
      throw error;
    }
  }
  return null;
}

async function availableBytes(root) {
  const usage = await statfs(root);
  return usage.bavail * usage.bsize;
}

export async function prepareRunnerStorage({
  root = "/",
  env = process.env,
  platform = process.platform,
} = {}) {
  await assertHostedUbuntu({ root, env, platform });
  const availableBytesBefore = await availableBytes(root);
  // Validate the complete allowlist before any deletion. Never traverse an
  // image path whose parent has been redirected outside the runner image.
  const candidates = await Promise.all(
    unusedImageDirectories.map(async (path) => ({
      path,
      skip: await candidate(root, path),
    })),
  );
  const removed = [];
  const skipped = [];
  for (const { path, skip } of candidates) {
    const unsafe = skip ?? (await candidate(root, path));
    if (unsafe) {
      skipped.push(unsafe);
      continue;
    }
    // Recursive rm unlinks nested symlinks without following their targets.
    await rm(join(root, path.slice(1)), { recursive: true });
"}

