test("Windows execution partitions keep all eight native jobs directly required", () => {
  assert.deepEqual(windowsPartitions, [1, 2, 3, 4, 5, 6, 7, 8]);
  const workflow = readFileSync(
    new URL("../../.github/workflows/windows-workspace.yml", import.meta.url),
    "utf8",
  );
  assert.match(workflow, /name: Windows workspace tests .*\/8\)/u);
  phase("consume", join(root, "evidence/stale"), JSON.stringify(trust), { ...env, GITHUB_RUN_ATTEMPT: "2" }, 1);
  assert.ok(!existsSync(target));
  phase("consume", join(root, "evidence/missing-trust"), "{}", env, 1);
  assert.ok(!existsSync(target));
  phase("loader-control", join(root, "evidence/loader-control"), JSON.stringify(trust));
  renameSync(target, join(root, "target/loader-control-output"));
  const output = join(root, "evidence/ignored-results");
  const result = phase("consume", output, JSON.stringify(trust));
  assert.doesNotMatch(result.stderr, /^\s*(?:Compiling|Checking) /mu);
  const receipt = JSON.parse(readFileSync(join(output, "receipt.json"), "utf8"));
  const backendReport = JSON.parse(readFileSync(join(output, "report.json"), "utf8"));
  assert.equal(backendReport.schema, 1); assert.deepEqual(Object.keys(backendReport.suites), Object.keys(BACKEND_SUITES));
  assert.equal(Object.keys(receipt.suites).length, 6, "Bridge/folder belong in the separate ignored receipt");
  assert.equal(receipt.kind, "linux-ignored"); assert.equal(receipt.executedTests, 12, "Bridge is derived, not a duplicated four-case constant");
  assert.equal(receipt.schema, process.platform === "linux" ? 2 : "linux-archive-fixture-v1");

  const authority = { ...trust, sourceSha: env.GITHUB_SHA, runId: env.GITHUB_RUN_ID, runAttempt: env.GITHUB_RUN_ATTEMPT, fixtureRuntime: process.platform === "linux" ? undefined : { qualification: "not-native-linux" } };
  assert.equal(verifyArchivedBackendEvidence(artifact, output, authority).executedTests, 12);
  const fullAuthority={...authority,jobResults:{producer:"success",consumers:"success",ignored:"success"}};
  const defaultOutputs=[1,2].map(shard=>join(root,`evidence/default-${shard}`));
  assert.equal((await collectLinuxWorkspace(artifact,defaultOutputs,output,fullAuthority)).ignoredTests,12);
  for(const field of ["producer","consumers","ignored"]) for(const status of ["failure","cancelled","skipped",""]) await assert.rejects(collectLinuxWorkspace(artifact,defaultOutputs,output,{...fullAuthority,jobResults:{...fullAuthority.jobResults,[field]:status}}));
#!/usr/bin/env bash
# Run from src-tauri (or a fixture workspace); preserve each platform's cohort.
set -e -o pipefail
usage() {
    echo "Usage: workspace-coverage.sh linux | macos | macos-host" >&2
    exit 2
}
case "${1:-}" in
    linux|macos|macos-host) platform="$1" ;;
    *) usage ;;
esac
[ "$#" = 1 ] || usage
if [ "$platform" = linux ]; then
    ulimit -c 262144
else
    # Hosted ARM has 3 CPUs/7 GiB. The complete four-job cohort accumulated
    # substantial compression/swap; bound compilation independently of tests.
    # Scope admission here, after cache restore; test workers stay at four.
    export CARGO_BUILD_JOBS=2
fi
run_phase() {
    local phase="$1"
    shift
    if [ "$platform" != linux ] && [ "$(uname -s)" = Darwin ]; then
        # Diagnostic snapshots are not acceptance gates. time retains the actual
        # command's exit status and reports CPU time and maximum child RSS;
        # that RSS is not the peak aggregate memory of concurrent compilers.
        echo "native-resource phase=$phase"

