test("Linux coverage environment failure cannot be masked by eval or admit execution", async t => {
  const {spawnSync}=await import("node:child_process");
  const {copyFileSync}=await import("node:fs");
  const root=mkdtempSync(path.join(os.tmpdir(),"mesh-linux-env-"));
  t.after(()=>rmSync(root,{recursive:true,force:true}));
  mkdirSync(path.join(root,"scripts/ci"),{recursive:true});mkdirSync(path.join(root,"bin"));
  const wrapper=path.join(root,"scripts/ci/linux-workspace.sh");
  copyFileSync(new URL("../ci/linux-workspace.sh",import.meta.url),wrapper);
  writeFileSync(path.join(root,"bin/cargo"),'#!/usr/bin/env bash\nprintf "%s\\n" "export LLVM_PROFILE_FILE=invalid"\nexit 37\n',{mode:0o755});
  writeFileSync(path.join(root,"bin/node"),'#!/usr/bin/env bash\ntouch "$MESH_ENV_EXECUTED"\n',{mode:0o755});
  const marker=path.join(root,"executed");
  const result=spawnSync("bash",[wrapper,"produce",path.join(root,"archive")],{env:{...process.env,PATH:`${path.join(root,"bin")}:${process.env.PATH}`,MESH_ENV_EXECUTED:marker},encoding:"utf8"});
  assert.equal(result.status,37);assert.equal(existsSync(marker),false);
});
EOF
